//---------------------------------------------------------
// Sous programme SIM7600_Init
// Auteur: RolleC
// Desc.: sous programme d'initialisation du SIM7600
// Ver. Date: V00 20250528 Crï¿½ation (YYYYMMDD)	
//---------------------------------------------------------

void SIM7600_Init(void)
{
    char cptStart = 100;
    startMode = true; // debut du start mode 
    Uart2SendString_modem("AT\r\n"); // test de communication

    while (!modemOK && !modemStartPin && !modemStart)
    {
        __delay_ms(100);
        cptStart--;
        if (cptStart == 0)
        {
            Uart2SendString_modem("AT\r\n"); // test de communication
            cptStart = 100;
        }
    }; // attendre que le Modem demarre ou qu'il reponde

    if (noSIM) // si la carte SIM est manquante
    {
        // indique l'erreur
        LCD_Clear();
        LCD_Write_String("NO SIM");
        LCD_Cursor_Position(LCD_LINE_TWO, 1);
        LCD_Write_String("REBOOT");

        while (1); // bloque dans l'init jusqu'au reboot
    }
    else
    {
        ready = 0;
        modemOK = false;
        modemStart = false;
        modemStartPin = false;

        Uart2SendString_modem("ATE0\r\n"); // pas d'écho
        while (!modemOK); // attendre la reponse de la commande
        modemOK = false; // reset state

        Uart2SendString_modem("AT+CMGF=1\r\n"); //Definit le mode texte pour les SMS.
        while (!modemOK); // attendre la reponse de la commande
        modemOK = false; // reset state

        Uart2SendString_modem("AT+CMGD=1,4\r\n"); //Supprime tous les SMS stockes.
        while (!modemOK); // attendre la reponse de la commande
        modemOK = false; // reset state

        Uart2SendString_modem("AT+CNMI=2,1,0,0,0\r\n"); //Configure les notifications lors de la réception d'un SMS.
        while (!modemOK); // attendre la reponse de la commande
        modemOK = false; // reset statee 

        startMode = false; // fin du start mode
        modemStatus_OK = true;
    }
}
